SELECT signal_id, symbol, interval_code, candle_open_time, origin, status, attempts, updated_at, completed_at, paper_position_id, failure_stage FROM crypto_ai.signal_processing_work WHERE signal_id IN (159285, 159407, 165415, 166819, 166821, 176927, 176934, 172201, 172587, 172588, 156850, 156852) OR paper_position_id IN (137, 143, 158, 162, 172, 182) ORDER BY candle_open_time, signal_id;